/**
 * @method
 * @name scwin.loadForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param bzProcsNo prtdepoId prtdepoPrnTpCd nm resdbzRegNo prtdepoObjKindCd prtdepoObjTpCd prtdepoRsnCd prtdepoRsnMngrghtTpCd prtdepoRsnFncTpCd prtdepoObjTpMiscContn prtdepoShrs miscPrtdepoRsnCd prtWithdYn prtdepoStrtDd prtdepoEndDd miscPrtdepoStrtDd miscPrtdepoEndDd
 * @returns
 * @hidden N
*/
scwin.loadForm = function (bzProcsNo, prtdepoId, prtdepoPrnTpCd, nm, resdbzRegNo, prtdepoObjKindCd, prtdepoObjTpCd, prtdepoRsnCd, prtdepoRsnMngrghtTpCd, prtdepoRsnFncTpCd, prtdepoObjTpMiscContn, prtdepoShrs, miscPrtdepoRsnCd, prtWithdYn, prtdepoStrtDd, prtdepoEndDd, miscPrtdepoStrtDd, miscPrtdepoEndDd) {
    /* sdd-asis-lifecycle:begin fn_LoadForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (bzProcsNo === "SUMPART") {
        return;
    }
    $c.util.getComponent("ipt_prtdepoId").setValue(prtdepoId);
    (($c.util.getComponent('slc_prtdepoPrnTpCd'))?.setValue?.(prtdepoPrnTpCd));
    $c.util.getComponent('ipt_nm').setValue(nm);
    $c.util.getComponent('ipt_resdbzRegNo').setValue(resdbzRegNo);
    (($c.util.getComponent('slc_prtdepoObjKindCd'))?.setValue?.(prtdepoObjKindCd));
    scwin.onChangeObjKindCd();
    (($c.util.getComponent('slc_prtdepoObjTpCd'))?.setValue?.(prtdepoObjTpCd));
    scwin.onChangeObjTpCd();
    (($c.util.getComponent('slc_prtdepoRsnCd'))?.setValue?.(prtdepoRsnCd));
    scwin.onChangeObjRsnCd();
    (($c.util.getComponent('slc_prtdepoRsnMngrghtTpCd'))?.setValue?.(prtdepoRsnMngrghtTpCd));
    scwin.onChangeObjRsnMnCd();
    (($c.util.getComponent('slc_prtdepoRsnFncTpCd'))?.setValue?.(prtdepoRsnFncTpCd));
    $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setValue(prtdepoObjTpMiscContn);
    $c.util.getComponent('ipt_prtdepoShrs').setValue($c.num.formatNumber(prtdepoShrs));
    (($c.util.getComponent('slc_miscPrtdepoRsnCd'))?.setValue?.(miscPrtdepoRsnCd));
    $c.util.getComponent("ipt_prtWithdYn").setValue(prtWithdYn);
    $c.util.getComponent('ipt_prtdepoStrtDd').setValue(prtdepoStrtDd);
    $c.util.getComponent('ipt_prtdepoEndDd').setValue(prtdepoEndDd);
    $c.util.getComponent('ipt_miscPrtdepoStrtDd').setValue(miscPrtdepoStrtDd);
    $c.util.getComponent('ipt_miscPrtdepoEndDd').setValue(miscPrtdepoEndDd);
    scwin.onloadDataSet();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onChangeObjKindCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onChangeObjKindCd = function () {
    /* sdd-asis-lifecycle:begin fn_OnChangeObjKindCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let defaultitem;
    const valueItem1 = "전환우선주:1|상환우선주:2|상환전환우선주:3|기타:6";
    const valueItem2 = "전환사채:4|신주인수권부사채:5|기타:6";
    const selectCtrl = $c.util.getComponent('slc_prtdepoObjTpCd');
    const sval = $c.util.getComponent('slc_prtdepoObjKindCd').getValue();
    let i;
    for (i = selectCtrl.options.length; i >= 0; i--) {
        selectCtrl.options[i] = null;
    }
    if (sval !== "1") {
        if (sval === "2") {
            defaultitem = valueItem1.split("|");
        } else {
            defaultitem = valueItem2.split("|");
        }
        for (i = 0; i < defaultitem.length; i++) {
            eld = defaultitem[i].split(":");
            selectCtrl.options[i] = new Option(eld[0]);
            selectCtrl.options[i].value = eld[1];
        }
    } else {
        selectCtrl.options[0] = new Option("해당사항없음");
        selectCtrl.options[0].value = "";
    }
    selectCtrl.options[0].selected = true;
    scwin.onChangeObjTpCd();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onChangeObjTpCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onChangeObjTpCd = function () {
    /* sdd-asis-lifecycle:begin fn_OnChangeObjTpCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getComponent('slc_prtdepoObjTpCd').getValue()=== "6") {
        $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setDisabled(false);
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
    } else {
        $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setValue("");
        $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setDisabled(true);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onChangeObjRsnCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onChangeObjRsnCd = function () {
    /* sdd-asis-lifecycle:begin fn_OnChangeObjRsnCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ('null' === "1") {
        if ($c.util.getComponent('slc_prtdepoRsnCd').getValue()=== "19") {
            $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setValue("");
            $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setDisabled(true);
            $c.util.getComponent('slc_prtdepoRsnFncTpCd').setValue("");
            $c.util.getComponent('slc_prtdepoRsnFncTpCd').setDisabled(true);
        } else {
            if (($c.util.getComponent('slc_prtdepoRsnCd').getValue() == null ? '' : String($c.util.getComponent('slc_prtdepoRsnCd').getValue())) === '') {
                $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setValue("");
                $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setDisabled(false);
                $c.util.getComponent('slc_prtdepoRsnFncTpCd').setValue("");
                $c.util.getComponent('slc_prtdepoRsnFncTpCd').setDisabled(false);
            } else {
                if ($c.util.getComponent('slc_prtdepoRsnCd').getValue()=== "01" || $c.util.getComponent('slc_prtdepoRsnCd').getValue()=== "02") {
                    $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setValue("");
                    $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setDisabled(false);
                    $c.util.getComponent('slc_prtdepoRsnFncTpCd').setValue("");
                    $c.util.getComponent('slc_prtdepoRsnFncTpCd').setDisabled(true);
                } else {
                    $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setValue("");
                    $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setDisabled(false);
                    $c.util.getComponent('slc_prtdepoRsnFncTpCd').setValue("");
                    $c.util.getComponent('slc_prtdepoRsnFncTpCd').setDisabled(true);
                }
            }
        }
    } else {
        if ($c.util.getComponent('slc_prtdepoRsnCd').getValue()=== "69" || $c.util.getComponent('slc_prtdepoRsnCd').getValue()=== "70") {
            $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setValue("");
            $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setDisabled(true);
            $c.util.getComponent('slc_prtdepoRsnFncTpCd').setValue("");
            $c.util.getComponent('slc_prtdepoRsnFncTpCd').setDisabled(true);
        } else {
            if (($c.util.getComponent('slc_prtdepoRsnCd').getValue() == null ? '' : String($c.util.getComponent('slc_prtdepoRsnCd').getValue())) === '') {
                $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setValue("");
                $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setDisabled(true);
                $c.util.getComponent('slc_prtdepoRsnFncTpCd').setValue("");
